	protected static readonly LanguageID LANG_ID_X86 = new LanguageID("x86:LE:32:default");
	protected static readonly LanguageID LANG_ID_X86_64 = new LanguageID("x86:LE:64:default");
	protected static readonly CompilerSpecID COMP_ID_DEFAULT = new CompilerSpecID("default");
	protected static readonly CompilerSpecID COMP_ID_GCC = new CompilerSpecID("gcc");
	protected static readonly CompilerSpecID COMP_ID_VS = new CompilerSpecID("windows");

	protected static readonly class LldbDebuggerPlatformMapper : DefaultDebuggerPlatformMapper {
