	}

	class Offers : DebuggerPlatformOffer
{	public static readonly Offers AARCH64_MACOS = new(, LANG_ID_AARCH64, COMP_ID_DEFAULT);
	public static readonly Offers I386_LINUX = new(, LANG_ID_X86, COMP_ID_GCC);
	public static readonly Offers I386_MACOS = new(, LANG_ID_X86, COMP_ID_GCC);
	public static readonly Offers I386_WINDOWS = new(, LANG_ID_X86, COMP_ID_VS);
	public static readonly Offers X86_64_LINUX = new(, LANG_ID_X86_64, COMP_ID_GCC);
	public static readonly Offers X86_64_MACOS = new(, LANG_ID_X86_64, COMP_ID_GCC);
	public static readonly Offers X86_64_WINDOWS = new(, LANG_ID_X86_64, COMP_ID_VS);


		string description;
		LanguageID langID;
		CompilerSpecID cSpecID;

		private Offers(string description, LanguageID langID, CompilerSpecID cSpecID) {
			this.description = description;
			this.langID = langID;
